const b = ($input.first() && $input.first().json && $input.first().json.body) || {};
const wo = (b.workout || 'treino').toString();
const mealsTotal = Number(b.mealsToday != null ? b.mealsToday : (b.mealsTotal || 0)) || 0;
const proteinEst = Number(b.proteinEst) || mealsTotal * 45;
const target = Number(b.proteinTarget) || 154;
const rem = Math.max(0, Math.round(target - proteinEst));
let flag = 'COMBUSTIVEL', msg;
if (mealsTotal === 0) { msg = 'Ainda nao registaste refeicoes hoje. Com ' + wo + ' no plano, comer E o treino mais importante — comeca ja.'; }
else if (rem > 50) { msg = 'Vais em ~' + proteinEst + 'g de proteina, faltam uns ' + rem + 'g para a meta. Bulk e constancia a mesa — nao pares.'; }
else { flag = 'EM DIA'; msg = 'Proteina no ponto (~' + proteinEst + 'g). E assim que se recupera de um dia de ' + wo + '. Continua.'; }
return [{ json: { coach: 'SANJI', flag, msg, proteinEst, rem, mealsTotal } }];
